sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 offset;
uniform float evolution;
uniform float scale;
uniform float2 stretch;
uniform float intensity;
uniform float seed;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
uniform float alpha;
uniform float octaves;
float hash13(float3 p) {
    p = fract(p * 0.1031);
    p += dot(p, p.zyx + 31.32);
    return fract((p.x + p.y) * p.z);
}
float vnoise(float3 p) {
    float3 i = floor(p);
    float3 f = fract(p);
    f = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
    float a = mix(hash13(i), hash13(i + float3(1, 0, 0)), f.x);
    float b = mix(hash13(i + float3(0, 1, 0)), hash13(i + float3(1, 1, 0)), f.x);
    float c = mix(hash13(i + float3(0, 0, 1)), hash13(i + float3(1, 0, 1)), f.x);
    float d = mix(hash13(i + float3(0, 1, 1)), hash13(i + float3(1, 1, 1)), f.x);
    return mix(mix(a, b, f.y), mix(c, d, f.y), f.z);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float unit = 0.4 * size.y * max(scale, 0.01);
    float3 p = float3((coord - size * 0.5 - offset) / (unit * max(abs(stretch), float2(0.01))) + seed * float2(29.3, 13.1), evolution);
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    float weight = 1.0;
    for (int i = 0; i < 9; i++) {
        if (float(i) >= octaves) break;
        float r = 1.0 - abs(vnoise(p) * 2.0 - 1.0);
        r = r * r * weight;
        weight = clamp(r * 1.6, 0.0, 1.0);
        sum += amp * r;
        norm += amp;
        amp *= 0.5;
        p = float3(p.xy * 2.07 + float2(5.3, 11.7), p.z * 1.6 + 2.3);
    }
    float v = clamp(pow(sum / max(norm, 0.0001) * 1.4, 1.0 / max(intensity, 0.1)), 0.0, 1.0);
    float3 fill = mix(float3(color1.rgb), float3(color2.rgb), v);
    float amount = clamp(alpha, 0.0, 1.0) * mix(float(color1.a), float(color2.a), v);
    float3 base = float3(src.rgb) / float(src.a);
    return half4(half3(mix(base, fill, amount)) * src.a, src.a);
}
